function AllCases(): React.Node {
  return (
    <ScrollView
      style={{flex: 1}}
      contentContainerStyle={{paddingHorizontal: 12, paddingBottom: 24}}>
      <View style={{paddingVertical: 12, gap: 6}}>
        <Text style={{fontSize: 15, fontWeight: '600', color: LABEL_COLOR}}>
          {'Grid conformance corpus — 341 cases'}
        </Text>
        <Text style={{fontSize: 12, color: SECONDARY_COLOR, lineHeight: 17}}>
          {
            'Every case is laid out at the 900pt width the Safari oracle ' +
            'used, so only its left edge fits on a phone, and the boxes are ' +
            'tinted so the packing is visible at all. This screen is not ' +
            'meant to be read case by case: it exists so the measured rects ' +
            'can be published and compared. Run ' +
            'packages/rn-tester/scripts/grid-conformance-verify.js to check ' +
            'every rect against Safari.'
          }
        </Text>
      </View>
      {CASES.map(c => (
        <Case
          key={c.id}
          id={c.id}
          containerStyle={c.style}
          items={c.items}
        />
      ))}
    </ScrollView>
  );
}

export default {
  title: 'Grid Conformance',
  category: 'Layout',
  description:
    'Renders the whole grid / grid-lanes conformance corpus and publishes every measured rect, for grid-conformance-verify.js to compare against Safari. Not meant to be read — meant to be measured.',
  examples: [
    {
      title: 'All cases',
      name: 'all',
      // The screen owns its scrolling. Without this the example container
      // pads around it, which insets the ScrollView itself: the indicator
      // floats off the display's right edge and the content gains a second
      // frame of chrome. The padding belongs INSIDE, on the content.
      fullBleed: true,
      render: (): React.Node => <AllCases />,
    },
  ],
} as RNTesterModule;
